// src/app/core/guards/auth.guard.ts
var authGuard = (route, state) => {
  const auth = inject(AuthService);
  const external = inject(ExternalSessionService);
  const router = inject(Router);
  if (auth.isAuthenticated())
    return true;
  if (external.enabled) {
    if (auth.restoreExternalSession())
      return true;
    external.redirectToPortal();
    return false;
  }
  return router.createUrlTree(["/login"], { queryParams: { returnUrl: state.url } });
};

// src/app/core/guards/permission.guard.ts
var permissionGuard = (route) => {
  const auth = inject(AuthService);
  const router = inject(Router);
  if (!auth.isAuthenticated()) {
    return router.createUrlTree(["/login"]);
  }
  const permission = route.data?.["permission"];
  const anyPermission = route.data?.["anyPermission"];
  if (permission && !auth.hasPermission(permission)) {
    return router.createUrlTree(["/forbidden"]);
  }
  if (anyPermission && !auth.hasAny(anyPermission)) {
    return router.createUrlTree(["/forbidden"]);
  }
  return true;
};

