function findLocalResponse(message) {
  const lower = message.toLowerCase();
  let bestMatch = null;
  let bestScore = 0;
  for (const entry of LOCAL_RESPONSES) {
    let score = 0;
    for (const kw of entry.keywords) {
      if (lower.includes(kw)) {
        score += kw.length;
      }
    }
    if (score > bestScore) {
      bestScore = score;
      bestMatch = entry;
    }
  }
  return bestMatch ? bestMatch.reply : FALLBACK_REPLY;
}
function formatChatHtml(raw) {
  let html = raw;
  html = html.replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
  html = html.replace(/^[\t ]*[-*]\s+(.+)$/gm, '<div style="display:flex;gap:8px;align-items:baseline;margin:2px 0"><span style="color:var(--accent-indigo);flex-shrink:0">\u2022</span><span>$1</span></div>');
  html = html.replace(/^[\t ]*(\d+)\.\s+(.+)$/gm, '<div style="display:flex;gap:8px;align-items:baseline;margin:2px 0"><span style="color:var(--accent-indigo);font-weight:600;flex-shrink:0;min-width:16px">$1.</span><span>$2</span></div>');
  const lines = html.split("\n");
  const formatted = [];
  let inTable = false;
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.includes(" | ") && (trimmed.match(/\|/g) || []).length >= 2) {
      if (!inTable) {
        formatted.push(`<div style="margin:8px 0;font-size:12px;line-height:1.7;font-family:'SF Mono',monospace">`);
        inTable = true;
      }
      const cells = trimmed.split(" | ").map((cell) => cell.trim());
      const styledRow = cells.map((cell, i30) => {
        if (i30 === 0)
          return `<span style="color:var(--accent-indigo);font-weight:600">${cell}</span>`;
        return `<span style="opacity:0.85">${cell}</span>`;
      }).join(' <span style="opacity:0.25">|</span> ');
      formatted.push(`<div style="padding:3px 0;border-bottom:1px solid rgba(127,127,127,0.08)">${styledRow}</div>`);
    } else {
      if (inTable) {
        formatted.push("</div>");
        inTable = false;
      }
      formatted.push(line);
    }
  }
  if (inTable) {
    formatted.push("</div>");
  }
  html = formatted.join("\n");
  html = html.replace(/^(<b>[^<]+<\/b>)\s*$/gm, '<div style="margin:10px 0 4px;font-size:13px;font-weight:700;letter-spacing:0.02em;border-bottom:1px solid rgba(127,127,127,0.12);padding-bottom:4px">$1</div>');
  return html;
}
