function exportDashboardReportCsv(snapshot, request) {
  const { sections } = request;
  const blocks = [];
  blocks.push(["NEOXTECH Dashboard Report"]);
  blocks.push([snapshot.title]);
  blocks.push(["Generated", snapshot.generatedAt.toISOString()]);
  blocks.push([]);
  if (sections.currentFilters) {
    blocks.push(["Active filters"]);
    blocks.push(["Filter", "Value"]);
    snapshot.filters.forEach((f27) => blocks.push([f27.label, f27.value]));
    blocks.push([]);
  }
  if (sections.overallProgress) {
    const o36 = snapshot.overall;
    blocks.push(["Overall progress"]);
    blocks.push(["Metric", "Value"]);
    blocks.push(["Completion", o36.completionRate]);
    blocks.push(["Status", o36.completionStatus]);
    blocks.push(["Planned", o36.totalPlanned]);
    blocks.push(["Completed", o36.completed]);
    blocks.push(["In progress", o36.inProgress]);
    blocks.push(["Queued", o36.pending]);
    blocks.push(["Blocked", o36.blocked]);
    blocks.push(["Velocity", o36.weeklyRate]);
    blocks.push([]);
  }
  if (sections.ringProgress && snapshot.rings.length) {
    blocks.push(["Ring progress"]);
    blocks.push(["Ring", "Planned", "Completed", "Active", "Queued", "Blocked", "Completion %"]);
    snapshot.rings.forEach((r31) => blocks.push([
      r31.name,
      r31.totalKm,
      r31.completedKm,
      r31.inProgressKm,
      r31.pendingKm,
      r31.blockedKm,
      r31.completionPct
    ]));
    blocks.push([]);
  }
  if (sections.contractorPerformance && snapshot.contractors.length) {
    blocks.push(["Contractor performance"]);
    blocks.push(["Rank", "Contractor", "Planned", "Completed", "Active", "Completion %", "On-time %", "Status"]);
    snapshot.contractors.forEach((c33) => blocks.push([
      String(c33.rank),
      c33.name,
      c33.totalKm,
      c33.completedKm,
      c33.inProgressKm,
      c33.completionPct,
      c33.onTime,
      c33.status
    ]));
    blocks.push([]);
  }
  if (sections.constructionPipeline && snapshot.pipeline.length) {
    blocks.push(["Construction pipeline"]);
    blocks.push(["Step", "Progress", "Done", "Active", "Queued", "Blocked", "Status"]);
    snapshot.pipeline.forEach((p34) => blocks.push([
      p34.step,
      p34.completedPct,
      String(p34.done),
      String(p34.active),
      String(p34.queued),
      String(p34.blocked),
      p34.status
    ]));
  }
  const filename = `neox-dashboard-report-${fileStamp(snapshot.generatedAt)}.csv`;
  downloadCsv(filename, rowsToCsv(blocks));
}

