  get activeBillingTarget() {
    return this.billingTargetData[this.goalMonth] || this.billingTargetData["Jun 2024"];
  }
  get billingPercent() {
    const t34 = this.activeBillingTarget;
    return Math.round(t34.current / t34.target * 100);
  }
  onGoalMonthChange(value) {
    this.goalMonth = value;
  }
  closeFinNotifications() {
    this.showFinNotifications = false;
  }
  toggleFinNotifications(event) {
    event.stopPropagation();
    this.showFinNotifications = !this.showFinNotifications;
  }
  buildSalesPie() {
    const circumference = 2 * Math.PI * 80;
    let offset = 0;
    this.salesPieSegments = this.salesByProject.map((item, i30) => {
      const segLen = item.percent / 100 * circumference;
      const seg = {
        name: item.name,
        amount: item.amount,
        percent: item.percent,
        color: this.salesPieColors[i30] || "#93c5fd",
        dashArray: `${segLen} ${circumference - segLen}`,
        dashOffset: -offset
      };
      offset += segLen;
      return seg;
    });
  }
  buildTopContractors() {
    const data = this.topContractorsData[this.productsMonth] || this.topContractorsData["This Month"];
    const maxAmount = Math.max(...data.map((d29) => d29.amount), 1);
    const formatAmount = (v17) => v17 >= 1e6 ? "$" + (v17 / 1e6).toFixed(2) + "M" : "$" + Math.round(v17 / 1e3) + "K";
    this.topContractors = data.map((d29) => ({
      name: d29.name,
      amount: formatAmount(d29.amount),
      totalPO: formatAmount(d29.totalPO),
      poInvoiced: formatAmount(d29.poInvoiced),
      invoicedPercent: Math.round(d29.poInvoiced / d29.totalPO * 100),
      percent: Math.round(d29.amount / maxAmount * 100),
      color: d29.color
    }));
  }
  onProductsMonthChange(value) {
    this.productsMonth = value;
    this.buildTopContractors();
  }
  getSupplierMaxPO() {
    return Math.max(...this.topMaterialSuppliers.map((s37) => s37.totalPO), 1);
  }
  formatSupplierAmount(v17) {
    return v17 >= 1e6 ? "$" + (v17 / 1e6).toFixed(2) + "M" : "$" + Math.round(v17 / 1e3) + "K";
  }
  getSupplierDeliveryPct(s37) {
    return s37.totalPO > 0 ? Math.round(s37.delivered / s37.totalPO * 100) : 0;
  }
  ngOnInit() {
    document.addEventListener("click", this.finDocClickBound);
    this.applyFilters();
    this.buildRevenuePaths();
    this.buildSalesPie();
    this.buildMrcPaths();
    this.buildTopContractors();
  }
  ngOnDestroy() {
    document.removeEventListener("click", this.finDocClickBound);
  }
  applyFilters() {
    this.filterSalesRevenue();
    this.filterProjectStatus();
    this.filterProfitMargin();
    this.filterPaymentData();
    this.filterFunnelData();
    this.filterKpiCards();
    this.filterRevenueChart();
    this.filterBudgetHistory();
    this.filterCostCodes();
    this.filterMaterialTracking();
    this.filterDeliveryOrders();
    this.filterLpoLogs();
    this.filterCtcProjects();
  }
  filterSalesRevenue() {
    let data = [...this.allSalesRevenueData];
    if (this.selectedProjectType !== "All") {
      data = data.filter((d29) => d29.type === this.selectedProjectType);
    }
    const multiplier = this.timePeriodMultipliers[this.selectedTimePeriod] || 1;
    const yearScale = this.yearMultipliers[this.selectedYear] || 1;
    this.salesRevenueData = data.map((d29) => __spreadProps(__spreadValues({}, d29), {
      actual: +(d29.actual * multiplier * yearScale).toFixed(1),
      planned: +(d29.planned * multiplier * yearScale).toFixed(1)
    }));
  }
  filterProjectStatus() {
    let data = [...this.allProjectStatusData];
    if (this.selectedProjectType !== "All") {
      data = data.filter((d29) => d29.type === this.selectedProjectType);
    }
    const multiplier = this.timePeriodMultipliers[this.selectedTimePeriod] || 1;
    const yearScale = this.yearMultipliers[this.selectedYear] || 1;
    this.projectStatusData = data.map((d29) => __spreadProps(__spreadValues({}, d29), {
      inProgress: Math.round(d29.inProgress * multiplier * yearScale),
      iatApproved: Math.round(d29.iatApproved * multiplier * yearScale),
      onHold: Math.round(d29.onHold * multiplier * yearScale),
      completed: Math.round(d29.completed * multiplier * yearScale)
    }));
  }
  filterProfitMargin() {
    let sorted = [...this.allProfitMarginData].sort((a31, b14) => b14.margin - a31.margin);
    if (this.selectedProfitProject === "Top 5") {
      this.profitMarginData = sorted.slice(0, 5);
    } else {
      this.profitMarginData = sorted.filter((d29) => d29.project === this.selectedProfitProject);
      if (this.profitMarginData.length === 0) {
        this.profitMarginData = sorted.slice(0, 5);
      }
    }
  }
  filterPaymentData() {
    const multiplier = this.timePeriodMultipliers[this.selectedTimePeriod] || 1;
    const yearScale = this.yearMultipliers[this.selectedYear] || 1;
    const typeScale = this.selectedProjectType === "All" ? 1 : this.selectedProjectType === "Commercial" ? 0.45 : this.selectedProjectType === "Residential" ? 0.3 : 0.25;
    this.paymentData = {
      invoiceRaised: Math.round(this.basePaymentData.invoiceRaised * multiplier * typeScale * yearScale),
      paidReceived: Math.round(this.basePaymentData.paidReceived * multiplier * typeScale * yearScale)
    };
  }
  filterFunnelData() {
    this.funnelChartData = this.funnelMonthlyData.map((d29) => __spreadProps(__spreadValues({}, d29), {
      leads: this.funnelFilter === "All" || this.funnelFilter === "Leads" ? d29.leads : 0,
      awarded: this.funnelFilter === "All" || this.funnelFilter === "Awarded" ? d29.awarded : 0,
      lost: this.funnelFilter === "All" || this.funnelFilter === "Lost" ? d29.lost : 0
    }));
    const allVals = this.funnelChartData.flatMap((d29) => [d29.leads, d29.awarded, d29.lost]);
    this.funnelYMax = Math.ceil(Math.max(...allVals, 1) * 1.15 / 10) * 10;
    const step = Math.ceil(this.funnelYMax / 5);
    this.funnelYLabels = [];
    for (let i30 = 5; i30 >= 0; i30--) {
      this.funnelYLabels.push(step * i30);
    }
    this.funnelYMax = step * 5;
  }
  onFunnelFilterChange(value) {
    this.funnelFilter = value;
    this.filterFunnelData();
  }
  getFunnelBarHeight(value) {
    return this.funnelYMax > 0 ? value / this.funnelYMax * 100 : 0;
  }
  filterKpiCards() {
    const multiplier = this.timePeriodMultipliers[this.selectedTimePeriod] || 1;
    const yearScale = this.yearMultipliers[this.selectedYear] || 1;
    const typeScale = this.selectedProjectType === "All" ? 1 : this.selectedProjectType === "Commercial" ? 0.45 : this.selectedProjectType === "Residential" ? 0.3 : 0.25;
    const values = this.baseKpiValues.map((v17) => +(v17 * multiplier * typeScale * yearScale).toFixed(1));
    this.kpiCards = [
      { title: "Total Contract Value", value: "$" + values[0] + "M", change: 12.5, direction: "up", color: "blue" },
      { title: "Revenue Earned", value: "$" + values[1] + "M", change: 8.2, direction: "up", color: "purple" },
      { title: "Total Expenditure", value: "$" + values[2] + "M", change: 16.3, direction: "up", color: "green" },
      { title: "Gross Profit", value: "$" + values[3] + "M", change: 3.8, direction: "down", color: "red" }
    ];
  }
  onTimePeriodChange(value) {
    this.selectedTimePeriod = value;
    this.applyFilters();
  }
  onYearChange(value) {
    this.selectedYear = value;
    this.applyFilters();
  }
  onProjectTypeChange(value) {
    this.selectedProjectType = value;
    this.applyFilters();
  }
  onProfitProjectChange(value) {
    this.selectedProfitProject = value;
    this.filterProfitMargin();
  }
  getMaxProjectStatus() {
    return Math.max(...this.projectStatusData.map((d29) => Math.max(d29.inProgress, d29.iatApproved, d29.onHold, d29.completed)));
  }
  getBarHeight(value) {
    const max = this.getMaxProjectStatus();
    return max > 0 ? value / max * 100 : 0;
  }
  getSalesMax() {
    return Math.max(...this.salesRevenueData.map((d29) => Math.max(d29.actual, d29.planned)));
  }
  getSalesBarHeight(value) {
    const max = this.getSalesMax();
    return max > 0 ? value / max * 100 : 0;
  }
  getPaymentMax() {
    return Math.max(this.paymentData.invoiceRaised, this.paymentData.paidReceived) * 1.1;
  }
  getPaymentBarWidth(value) {
    const max = this.getPaymentMax();
    return max > 0 ? value / max * 100 : 0;
  }
